import{_ as s,o as e,c as n,a2 as o}from"./chunks/framework.BAOEAOnu.js";const m=JSON.parse('{"title":"Runtime & Estrutura","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/project-structure.md","filePath":"deep-dive/project-structure.md","lastUpdated":1781623519000}'),t={name:"deep-dive/project-structure.md"};function p(d,a,c,i,r,l){return e(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="runtime-estrutura" tabindex="-1">Runtime &amp; Estrutura <a class="header-anchor" href="#runtime-estrutura" aria-label="Permalink to &quot;Runtime &amp; Estrutura&quot;">​</a></h1><h2 id="o-pacote-do-framework" tabindex="-1">O pacote do framework <a class="header-anchor" href="#o-pacote-do-framework" aria-label="Permalink to &quot;O pacote do framework&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.claude/          Claude Code — commands(17) · skills(32) · agents(9)</span></span>
<span class="line"><span>.codex/           Codex       — skills(32) · prompts(17)</span></span>
<span class="line"><span>.grok/            Grok Build  — skills(49 = 32 + 17 comandos-skill)</span></span>
<span class="line"><span>.agent/           Antigravity CLI — skills(49)</span></span>
<span class="line"><span>.agents/          Antigravity UI  — skills(49)</span></span>
<span class="line"><span>.codesl/          Runtime compartilhado (o &quot;motor&quot;)</span></span>
<span class="line"><span>AGENTS.md         Instruções globais (Codex/Grok/Antigravity)</span></span>
<span class="line"><span>bin/cli.js        Instalador npx</span></span></code></pre></div><h2 id="o-runtime-codesl" tabindex="-1">O runtime <code>.codesl/</code> <a class="header-anchor" href="#o-runtime-codesl" aria-label="Permalink to &quot;O runtime \`.codesl/\`&quot;">​</a></h2><p>É o que dá <strong>determinismo</strong> ao método — o que não pode ficar a cargo do modelo.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.codesl/</span></span>
<span class="line"><span>  scripts/        status.sh · next-id.sh · done.sh · feature-pr.sh ·</span></span>
<span class="line"><span>                  get-branch-metadata.sh · pattern-search.sh ·</span></span>
<span class="line"><span>                  architecture-discover.sh · log-jsonl.sh · log-iteration.sh …</span></span>
<span class="line"><span>  fragments/      fragmentos de comando (tdd, startup-test)</span></span>
<span class="line"><span>  templates/      templates de docs (feature, hotfix)</span></span>
<span class="line"><span>  manifest.json   registro de referência</span></span></code></pre></div><p>Os comandos chamam esses scripts por <strong>caminho relativo</strong> (<code>.codesl/scripts/status.sh</code>), então cada projeto precisa do <code>.codesl/</code> na raiz — é o que o <code>init</code> faz.</p><div class="tip custom-block"><p class="custom-block-title">Tipo de log <code>add</code></p><p>Os scripts usam <code>fix|enhance|refactor|add|remove|config</code> como tipos de iteração. O <code>add</code> aqui é <strong>valor de domínio</strong> (não a marca) — <code>status.sh</code> conta entradas <code>&quot;type&quot;:&quot;add&quot;</code> para detectar features concluídas.</p></div><h2 id="artefatos-gerados-num-projeto" tabindex="-1">Artefatos gerados num projeto <a class="header-anchor" href="#artefatos-gerados-num-projeto" aria-label="Permalink to &quot;Artefatos gerados num projeto&quot;">​</a></h2><p>Conforme você usa os comandos, o método cria:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>  owner.md, product.md          (sl.init)</span></span>
<span class="line"><span>  features/&lt;NNNN&gt;F-&lt;slug&gt;/</span></span>
<span class="line"><span>    about.md                    (sl.new)</span></span>
<span class="line"><span>    plan.md                     (sl.plan)</span></span>
<span class="line"><span>    tasks.md                    (sl.plan/build)</span></span>
<span class="line"><span>    decisions.jsonl             (log de decisões)</span></span>
<span class="line"><span>    iterations.jsonl            (log de iterações)</span></span>
<span class="line"><span>CHANGELOG / changelog           (sl.done)</span></span></code></pre></div><p>IDs seguem <code>[NNNN][L]</code> (ver skill <code>sl-id-convention</code>): <code>F</code> feature, <code>H</code> hotfix, <code>CHG</code> chore.</p><h2 id="independencia" tabindex="-1">Independência <a class="header-anchor" href="#independencia" aria-label="Permalink to &quot;Independência&quot;">​</a></h2><p>Por usar <code>.codesl/</code> (e não o <code>.codeadd/</code> do método original), o Se Liga AI <strong>coexiste</strong> com o code-addiction no mesmo projeto sem colidir.</p>`,14)])])}const h=s(t,[["render",p]]);export{m as __pageData,h as default};
